(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zu"] = {"ui":{"skip":"Yeqela ukuya okuqukethwe","back":"← Buyela ku-AI-gile","lang.button":"Ulimi: {name}","lang.dialog":"Khetha ulimi","lang.search":"Sesha izilimi","lang.none":"Alukho ulimi oluhambisanayo","lang.notYet":"{name} alukahunyushwa okwamanje","theme.aria":"Shintsha itimu: ekhanyayo, emnyama noma emnyama bhuqe","theme.toLight":"Shintshela etimini ekhanyayo","theme.toDark":"Shintshela etimini emnyama","theme.toBlack":"Shintshela etimini emnyama bhuqe (emnyama ngempela, ilungele izikrini ze-OLED)","words.underline":"Dweba umugqa ngaphansi kwalawa magama ekhasini","words.underlineHelp":"Beka i-mouse phezu kwegama elinamachashazi noma ulithinte ukuze ubone ukuthi lisho ukuthini.","index.title":"AI-gile: iqembu lakho le-AI lokuthuthukisa, ebhodini elilodwa","index.description":"I-AI-gile yibhodi le-kanban lamaqembu e-AI abhala ikhodi. Asebenza ngenkathi ulele; wena uthola inqwaba emfushane yezinto zokuthatha isinqumo, ukuhlola nokwamukela.","hero.logoAlt":"Isithonjana sebhodi le-AI-gile","hero.h1.html":"Iqembu lakho le-AI lokuthuthukisa, ebhodini&nbsp;elilodwa.","hero.alpha":"🐣 I-pre-alpha evaliwe","hero.alphaTitle":"Kusenesikhathi futhi akukaqedwa: siyabonga ngokuzama!","hero.lede":"Akha ngenkathi ulele. Uvuka kunqwaba emfushane eyodwa: imibuzo embalwa, izinto ezimbalwa zokuhlola, idayimane elilodwa noma amabili ansomi. Chofoza, yamukela, ubuyele ekhofini lakho.","dl.windows":"Uhlelo lwe-Windows","dl.browser":"Lusebenzise kusiphequluli sakho","dl.messenger":"📱 I-Messenger yefoni yakho","dl.soon":"Kuyeza maduze","dl.notify":"🔔 Ngazise lapho livulwa","dl.notifySmall":"I-alpha noma i-beta","hero.secondary":"I-agile, kodwa iqembu alidingi ikhofi le-stand-up. (Nokho liyazenza ama-stand-up.)","pitch.h2":"I-AI-gile ngamagama amaningi noma amancane njengoba ufuna","pitch.lede":"Khetha ubude, kusukela egameni elilodwa kuya kwangu-144. Ubude ngabunye buyincazelo yabo, ebhalelwe leso silinganiso. Donsa isilayidi noma sebenzisa imicibisholo.","pitch.rangeLabel":"Ubude ngamagama","pitch.dice":"🎲 enye inguqulo","pitch.words.one":"igama elingu-{n}","pitch.words.other":"amagama angu-{n}","pitch.letters.one":"uhlamvu olungu-{n}","pitch.letters.other":"izinhlamvu ezingu-{n}","pitch.chars.one":"uhlamvu olungu-{n}","pitch.chars.other":"izinhlamvu ezingu-{n}","count.line.html.one":"ikhadi elingu-{n} ebhodini khona manje","count.line.html.other":"amakhadi angu-{n} ebhodini khona manje","people.humans.html.one":"👥 umuntu ongu-{n}","people.humans.html.other":"👥 abantu abangu-{n}","people.agents.html.one":"🤖 i-ejenti engu-{n}","people.agents.html.other":"🤖 ama-ejenti angu-{n}","people.working.html.one":"⚡ {n} basebenza khona manje","people.working.html.other":"⚡ {n} basebenza khona manje","pre.title":"AI-gile: kukhona okwakhiwayo","pre.description":"Kukhona okwakhiwayo lapha: ibhodi lapho amaqembu e-AI akha lokho okucelayo, futhi akufundise ngesikhathi esebenza. Okwamanje yi-pre-alpha evaliwe nabangani.","pre.h1":"Kukhona okwakhiwayo lapha. 🤫","pre.line":"Ibhodi lapho amaqembu e-AI akha lokho okucelayo, futhi akufundise ngesikhathi esebenza. Okwamanje yi-pre-alpha evaliwe nabangani.","pre.btn":"🔔 Ngazise lapho livulwa","pre.peek":"Ngemuva kwengilazi: ibhodi langempela, bukhoma. Ikhadi ngalinye liwumugqa onombala.","pre.peekFake":"Ngemuva kwengilazi: libukeka kanje ibhodi elisebenzayo.","features.aria":"Okwenzayo","f.pile.h":"Inqwaba eyodwa yakho","f.pile.html":"<b>Kuwe</b> iqoqe konke okukulindele kuwo wonke amaphrojekthi: imibuzo, izinto zokuhlola, imisebenzi umuntu kuphela ayenzayo. Ulayini wakho ukutshela ukuthi yini elandelayo nokuthi kuthatha isikhathi esingakanani.","f.sleep.h":"Amaqembu asebenza ulele","f.sleep.p":"Iphrojekthi ngayinye inomholi neqembu lama-ejenti e-AI. Phawula ekhadini futhi iqembu liyavuka, lenze umsebenzi, liwubuyisele nezinyathelo umuntu ozikhathele angazilandela.","f.tester.h":"Umhloli we-AI uhlola kuqala","f.tester.p":"Ngaphambi kokuba kukufinyelele, umhloli ulandela izinyathelo kukhophi yohlelo bese ekukhombisa ayekubonile, ngesithombe-skrini. Hlola ngokushesha okwedlulile bese wamukela ngokuchofoza kanye.","f.proof.h":"Ubufakazi, hhayi izithembiso","f.proof.p":"Ukudluliselwa ngakunye kukhombisa okushintshile: amafayela, umahluko, izithombe-skrini. Akudingeki uvule uhlelo ngalunye ukuze ubone ukuthi sekuphelile yini.","f.chat.h":"Xoxa nabaholi bakho","f.chat.p":"Umugqa ofana nowe-Discord: isithonjana esisodwa kuphrojekthi ngayinye, amadayimane ansomi kokudinga wena. Thumela umholi umbono; bayiguqulela emakhadini nasepulanini, nenkinobho ethi ✅ Qala.","f.tidy.h":"Iziqoqa ngokwayo","f.tidy.p":"Amakhadi ahlobene ayahlangana abe linye, izihloko ezididayo ziyalungiswa, futhi ukuhlolwa kwamathokheni kugcina ikhodi incane. Izinto ezimbalwa zokushintsha phakathi kwazo, okuncane ongacabanga ngakho.","f.private.h":"Kungokwakho, ekhompyutheni yakho","f.private.li1":"Ibhodi lisebenza emshinini wakho futhi lilandela wena kuphela.","f.private.li2":"Imilayezo eyimfihlo phakathi kwabantu ibethelwe isuka ekugcineni iye ekugcineni.","f.private.li3":"Awekho ama-akhawunti, awekho ama-tracker, awekho amakhukhi.","f.lang.h":"Ngolimi lwakho","f.lang.p":"Izilimi ezingaphezu kwekhulu namashumi amabili, kusukela esiDashi, isiWelsh nesiJapane kuya umphangi wasolwandle, isiYoda nesiKlingon, nokushintsha ngokushesha kubuyele esiNgisini emagameni ochwepheshe.","f.service.h":"Kusuka embonweni kuya kusevisi yangempela","f.service.p":"Wakhe okuthile nge-AI manje abantu sebekusebenzisa? Kumake njengesevisi futhi ibhodi likusiza ukuyiqhuba kahle: ukuhlola i-uptime, ikhasi lesimo lomphakathi, izigameko ezinokuhlaziywa okubhaliwe, izinguquko ezidinga u-Hamba, izipele ezihlolwa nsuku zonke. Usizo lufundisa isinyathelo ngasinye njengoba uqhubeka.","msgr.h2":"AI-gile Messenger: ithimba lakho ephaketheni lakho","msgr.p1":"Khuluma nethimba lakho le-AI ngaphandle kokuvula ibhodi. Xoxa nabaholi bamaphrojekthi akho nabangane bakho, ubone izinyathelo zokuhlola zekhadi futhi uziphendule, konke ngefoni yakho.","msgr.p2":"Ukuze uyixhume, skena ikhodi ye-QR ebhodini lakho. Okokuqala? Ingxoxo yedemo enobungane izokubonisa konke.","msgr.when":"I-Android kuqala, bese kuba inguqulo yewebhu yamafoni ne-iPhone.","msgr.who":"Umholi wephrojekthi yakho","msgr.b1":"Ukulungiswa kwemodi emnyama sekulungile. Ufuna izinyathelo zokuhlola?","msgr.b2":"Yebo ngiyacela!","msgr.b3":"1. Vula Izilungiselelo. 2. Khetha Okumnyama. Kubukeka kulungile?","tl.aria":"Isikhathi esisukela engxoxweni yokuqala kuya emgwaqweni wesikhathi esizayo","tl.h2":"Kusukela engxoxweni yokuqala kuya kokulandelayo","tl.lede":"Amadethi nezikhathi zangempela, ngesikhathi sendawo yakho. Ngemva kwanamuhla kuyisu, akukho madethi aqinisekisiwe.","tl.today":"Namuhla","tl.planned":"kuhlelwe","tl.cards.one":"ikhadi elingu-{n}","tl.cards.other":"amakhadi angu-{n}","join.h2":"Joyina","join.lede":"I-AI-gile yakhiwa umuntu oyinqaba onentshebe, one-AuDHD nezimpi ezimbalwa nempilo yengqondo, kanye nenqwaba yama-ejenti anesineke. Okwamanje iyimfihlo, kuyi-alpha evaliwe nabangani. Ungathanda ukuzama lapho ivuleka?","join.btn":"Bhalisa isithakazelo","join.small":"Sizokubhalela nge-imeyili, akukho okunye","footer.tag":"I-AI-gile. Awekho ama-tracker, awekho amakhukhi, awekho ikhofi le-stand-up.","footer.licence":"Ilayisense yebhizinisi","footer.status":"Isimo","footer.privacy":"Esikugcinayo","footer.thanks":"Amakholi ngenxa ye-ChilledChat","form.sending":"Iyathumela…","form.failed":"Akusebenzanga: zama futhi emuva kwesikhathi.","form.offline":"Asikwazanga ukufinyelela ku-AI-gile: zama futhi emuva kwesikhathi.","form.keep":"Sikusebenzisela kuphela ukukuphendula, bese sikususa. Awekho ama-tracker, awekho amakhukhi.","form.keepLink":"Esikugcinayo","interest.title":"I-AI-gile: ngazise lapho i-alpha ivulwa","interest.description":"Shiya i-imeyili yakho ukuze uzwe lapho i-alpha noma i-beta evaliwe ye-AI-gile ivulwa.","interest.h1":"🔔 Ngazise lapho livulwa","interest.lede":"I-AI-gile iku-pre-alpha evaliwe. Shiya i-imeyili yakho futhi sizobhala kanye kuphela, lapho kunendawo yakho.","interest.email":"I-imeyili yakho","interest.which":"Ukuhlolwa kuphi?","interest.alpha":"I-alpha evaliwe: ekuqaleni, ayikaphelele, ushintsho oluningi","interest.beta":"I-beta: iqinile kakhulu, kamuva","interest.both":"Noma iyiphi, nanoma iyiphi eza kuqala","interest.submit":"Ngifake ohlwini","interest.thanks":"Siyabonga! Usohlwini.","licence.title":"I-AI-gile: ilayisense yebhizinisi","licence.description":"Usebenzisa i-AI-gile ebhizinisini lakho? Faka isicelo selayisense yebhizinisi mahhala.","licence.h1":"📜 Ilayisense yebhizinisi","licence.lede":"Usebenzisa i-AI-gile emsebenzini? Sitshele ukuthi ungubani nokuthi wenzani. Uma kwenza okuhle, ilayisense ayibizi lutho.","licence.company":"Inkampani","licence.website":"Iwebhusayithi","licence.what":"Okwenzayo","licence.how":"Ikusiza kanjani umhlaba","licence.email":"I-imeyili","licence.submit":"Faka isicelo","licence.thanks":"Siyabonga! Sizophendula nge-imeyili.","status.title":"Isimo se-AI-gile","status.h1":"Isimo se-AI-gile","status.quiet":"Konke kuthule","status.intro":"Ingabe i-AI-gile iyasebenza manje? Leli khasi lihlola iwebhusayithi, ukwabelana ngamabhodi, izingcingo nokulanda njalo ngemizuzu engu-5.","status.up":"Iyasebenza (iphendule ngo-{ms} ms)","status.slow":"Ayiphendulanga ekuhloleni kokugcina, iyazama futhi","status.down":"Ayisebenzi: ayiphendulanga ekuhloleni okubili kokugcina","status.svc.web":"Iwebhusayithi","status.svc.web.offers":"Le sayithi: ukuthi iyini i-AI-gile, nefomu elithi ngazise","status.svc.boards":"Ukwabelana ngamabhodi","status.svc.boards.offers":"Amabhodi omphakathi, imilayezo phakathi kwabangane nezimemo","status.svc.calls":"Izingcingo","status.svc.calls.offers":"Izwi, ividiyo nokwabelana ngesikrini ku-AI-gile","status.svc.download":"Ukulanda","status.svc.download.offers":"Isifaki se-Windows nezixhumanisi zezimemo","status.checking":"Iyahlola…","status.offline":"Asikwazi ukufinyelela insizakalo yesimo okwamanje (iyazama futhi)","status.updated":"ibuyekezwe {ago}","status.justNow":"khona manje","status.min":"imizuzu engu-{n} edlule","status.hours":"amahora angu-{n} edlule","status.days":"izinsuku ezingu-{n} edlule","privacy.title":"I-AI-gile: esikugcinayo","privacy.h1":"Esikugcinayo","privacy.lede":"Ngamafuphi: kuphela lokho osithumelela kona, futhi hhayi isikhathi eside.","privacy.only":"Kuphela lokho osithumelela kona: lokho okubhala efomini, njenge-imeyili yakho. Akukho okunye ngawe.","privacy.sealed":"Kuvalwa ngophawu ukuze iseva yethu ingakwazi ukukufunda: kusesiphequluli sakho ngaphambi kokuthi kuhambe (esipheqululini esidala, ngokushesha nje uma kufika). Yibhodi lethu kuphela elingakuvula.","privacy.server":"Kususwa kuseva ngokushesha nje uma kufika ebhodini lethu. Noma yini esekhona ngemva kwezinsuku ezingu-30 iyasuswa noma kunjalo.","privacy.board":"Sikugcina ebhodini lethu kuze kube yilapho sesikuphendulile, bese sikususa nalapho.","privacy.none":"Awekho ama-tracker, awekho amakhukhi, akukho ukuhlaziywa.","privacy.local":"Ulimi lwakho nokukhetha kwakho ukukhanya noma ubumnyama kuhlala esipheqululini sakho. Akukaze kuthunyelwe kithi.","privacy.ask":"Ufuna kususwe ngokushesha? Phendula i-imeyili yethu usitshele.","live.h2":"Bukela ngenkathi yakhiwa, bukhoma","live.caption":"Wonke ikhadi lifihliwe: ubona isimo somsebenzi, hhayi amagama.","live.watching.one":"bukhoma: {n} uyabuka","live.watching.other":"bukhoma: {n} bayabuka","live.last.now":"Ikhadi lokugcina lihanjiswe nje manje","live.last.min.one":"Ikhadi lokugcina lihanjiswe umzuzu ongu-{n} owedlule","live.last.min.other":"Ikhadi lokugcina lihanjiswe imizuzu engu-{n} edlule","live.last.hour.one":"Ikhadi lokugcina lihanjiswe ihora elingu-{n} eledlule","live.last.hour.other":"Ikhadi lokugcina lihanjiswe amahora angu-{n} edlule","live.last.day.one":"Ikhadi lokugcina lihanjiswe usuku olungu-{n} olwedlule","live.last.day.other":"Ikhadi lokugcina lihanjiswe izinsuku ezingu-{n} ezedlule","live.offline":"Ibhodi elibukhoma lithatha ikhefu elifushane. Buya maduze.","live.cols":"Backlog|Okufanele kwenziwe|Kuyaqhubeka|Iqembu liyahlola|Kuwe ukuthi test|Kweqembu|Kuphelile"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Amarobhothi.","Nikeza."]},{"n":2,"texts":["Kanban yamarobhothi.","Ama-ejenti, ahlelekile.","Imibono, yakhiwe."]},{"n":3,"texts":["Ibhodi lamarobhothi lamahhala.","Imibono iba izici.","Kanban yama-ejenti, mahhala."]},{"n":5,"texts":["Ibhodi eliqhutshwa ngama-ejenti, lamahhala nje.","Wena ubhala amakhadi. Ama-ejenti akha.","Mahhala, ekhaya, ihloliwe, nenhlanhla encane."]},{"n":8,"texts":["Ibhodi le-kanban lamahhala lapho ama-ejenti e-AI asebenza khona.","Bhala umbono. Ama-ejenti awakhe. Wena uyawamukela.","I-agile yomuntu oyedwa namarobhothi amaningi anesineke nje."]},{"n":13,"texts":["Ibhodi le-kanban ekhompyutheni yakho lapho ama-ejenti e-AI athatha khona amakhadi.","Bhala umbono wakho. Iqembu lama-ejenti liyawakha lapho. Bese umhloli we-AI uyawuhlola ngemva kwalokho.","Mahhala, awekho ama-akhawunti, awekho ama-tracker: ibhodi, amarobhothi athile, wena nguwe oyinhloko."]},{"n":21,"texts":["I-AI-gile yibhodi le-kanban lokusebenza nama-ejenti e-AI abhala ikhodi. Wona athatha amakhadi bese wena uwahlola futhi uwamukele ngokwakho lapho eseqedile.","Iphrojekthi ngayinye ithola umholi kanye neqembu lama-ejenti e-AI. Phawula noma yiliphi ikhadi, bese iqembu liyavuka liqale ukusebenza ngokushesha okukhulu.","Yibhodi lemisebenzi yomuntu siqu, lamahhala, elisebenza ekhompyutheni yakho uqobo. Abasebenzi bangamarobhothi nje. Futhi ophendula ngokuthi yebo nguwe wedwa."]},{"n":34,"texts":["Ubeka imibono yakho ebhodini. Iqembu lama-ejenti e-AI liyiguqula ibe yizici ezisebenzayo, liyazihlola, bese liziletha kuwe nezinyathelo zokuzama. Akukho okubalwa njengokuphelile ngaphandle kokuthi wena uthi kunjalo. Konke kwenzeka ekhompyutheni yakho.","I-AI-gile yibhodi le-kanban elenziwe ekhaya, elakhiwa nguRich ngosizo olukhulu lwama-ejenti manje alawulwa yilo. Lamahhala, lisebenza ekhompyutheni yakho, futhi labelwana nabangani, alithengiswa muntu. Lakhelwe ukusiza nokujabulisa, akukho okunye okufihliwe nhlobo.","Cabanga ibhodi le-kanban elijwayelekile, namakholomu asuka ku-Backlog aze afike ku-Done, kodwa amakhadi athathwa ama-ejenti e-AI. Abika inqubekela phambili, abuza lapho ebambekile, futhi njalo alinde ukuvuma kwakho, uthi yebo noma cha."]},{"n":55,"texts":["I-AI-gile yibhodi le-kanban lapho iqembu lakhiwe ngama-ejenti e-AI. Iphrojekthi ngayinye inomholi ohlela umsebenzi, nabasizi abawakhayo. Uma isici sesilungile, umhloli we-AI uyasizama, athathe nesithombe-skrini, bese sifika enqwabeni yakho. Ungasamukela, noma uphawule bese iqembu liqala kabusha ukusebenza ngokukhulu ukunaka. Konke kulula futhi kucacile, ngakho ungabuyela ekhofini lakho.","Laqala njengendlela yomuntu oyedwa yokulandelela izikhathi eziningi zokubhala ikhodi nge-AI ngasikhathi sinye, laze lakhula laba yibhodi langempela. Lisebenza emshinini wakho, alidingi i-akhawunti, futhi alinawo ama-tracker. Lamahhala kubangani nakuwo wonke onelukuluku. Alikaphelele, ngakho lindela ubukhali obuthile nezimanga ezimbalwa ngezikhathi ezithile. Kungcono ukuqala kancane, kanjalo siyakhula ndawonye nabangani.","Nanku iqiniso eliqinile. Kusadingeka ube nemibono yakho, futhi kusadingeka uhlole imiphumela ngokwakho. I-AI-gile yenza konke okuphakathi: igcina amakhadi ehleleke kahle, ivusa i-ejenti efanele uma uphawula, ikhombisa ncamashi okushintshile, futhi ikubeka konke enqwabeni eyodwa emfushane eyakho kuphela. Ukucabanga nokukhetha kusalokhu kungokwakho, futhi lokho kunjalo ngenhloso."]},{"n":89,"texts":["I-AI-gile yibhodi le-kanban lamahhala olisebenzisa ekhompyutheni yakho uqobo. Esikhundleni sabantu, iphrojekthi ngayinye inalo iqembu lama-ejenti e-AI: umholi oguqula imibono yakho ibe amakhadi nepulani, nabasizi abathatha amakhadi ngokulandelana kokubaluleka. Uma okuthile sekwakhiwe, umhloli we-AI ulandela izinyathelo zokuhlola bese ekukhombisa lokho akubonile ngesithombe-skrini. Bese kulinda enqwabeni eyodwa ethi Kuwe. Uyakwamukela, noma uphawule bese iqembu lizama futhi kusukela ekuqaleni. Akukho nakanye okufika ku-Done ngaphandle kwakho wena. Wonke umsebenzi wenzeka ekhompyutheni yakho, futhi awudingi i-akhawunti ukuze uwusebenzise.","Ezinye izici ongase ungazilindele. Umqaphi wasebusuku ugcina ikholomu ethi To do igcwele ngenkathi ulele, ekhetha amakhadi angadingi mpendulo evela kuwe. Isibali samathokheni sikhombisa ukuthi ama-ejenti asebenzise malini namuhla nalesi sonto, futhi imodi ethi No Token Mode iwatshela ukuba ayeke ukusebenzisa. Ungathumela imilayezo kubangani, futhi imilayezo eyimfihlo ibethelwe ngokuphelele. Ibhodi likhuluma izilimi ezingaba ngu-120, kubandakanya isiDashi, isiFlemish, umphangi wasolwandle nesiKlingon. Akukho kulokhu okubiza lutho, futhi akekho ozama ukukudayisela lona. Konke lokhu kwenzelwe ukuba ulale kahle, wazi ukuthi umsebenzi uqhubeka.","I-AI-gile iyiphrojekthi encane, yomuntu siqu, hhayi inkampani. URich wayefuna ukunakekela amaphrojekthi amaningi e-AI ngaphandle kokuvula uhlelo ngalunye ukuze alihlole, ngakho yena nama-ejenti akha ibhodi, base besebenzisa lona ibhodi ukwakha okusele kwalo uqobo. Iku-pre-alpha evaliwe, okusho ukuthi isebenza, ikakhulukazi, kwabangani abambalwa kuphela. Alikho ikhasi lamanani, alikho ileta yezindaba, futhi alikho icebo lokukhula. Uma lizwakala linomsebenzi kuwe, ungacela ukulizama lapho livuleka kancane nje. Uma ufuna ukuzama, bhala nje ukucela, bese sikuphendula ngokushesha uma sesikulungele kahle."]},{"n":144,"texts":["I-AI-gile yibhodi le-kanban lomuntu oyedwa nama-ejenti amaningi e-AI. Lisebenza ekhompyutheni yakho uqobo futhi lamahhala ngokuphelele. Wengeza amaphrojekthi, futhi iphrojekthi ngayinye ithola umholi neqembu elincane. Uxoxa nomholi, kufana kakhulu ne-Discord, uchaze umbono wakho; umholi uwuguqulela emakhadini nasepulanini, bese elinda ukuthi ucindezele u-Qala. Iqembu lisebenza ngamakhadi ngokulandelana kokubaluleka, lisebenzisa umugqa wemiyalo olula owenzelwe amamodeli olimi. Ngaphambi kokuba kukubuyele, umhloli we-AI ulandela izinyathelo kukhophi yohlelo bese enamathisela isithombe-skrini. Umsebenzi oqediwe uwela enqwabeni yakho kanye namafayela ashintshile nomahluko wawo. Uyawamukela, noma ushiye isikhumbuzo bese iqembu livuka lizame futhi. Wena kuphela ongashintshela ikhadi ku-Done, akekho omunye. Konke okwenziwayo kuyabonakala, ngakho awudingi ukuthemba ngokungaboni. Ibhodi lilula, linesineke, futhi lihlala lilinde izinqumo zakho ngokuthula okukhulu. Kuphelele kumuntu ofuna ukunyakazisa umsebenzi ngaphandle kokuhlala kuwo usuku lonke.","Usuku ne-AI-gile, kafushane. Kusihlwa uphawula amazwana ambalwa: le nkinobho isendaweni engafanele, lolo hlu kufanele luhlelwe, ingabe singaba nemodi emnyama yini. Uyalala. Ama-ejenti afunda amazwana, enze izinguquko, azihlole, bese ezibuyisela kuwe. Uma ikholomu ethi To do iphela, umqaphi wasebusuku uyigcwalisa evela ku-backlog ngamakhadi angadingi mpendulo evela kuwe. Ekuseni kunenqwaba eyodwa emfushane: imibuzo embalwa nezinto ezimbalwa zokuzama, ngayinye inezinyathelo umuntu onokulala angazilandela kanye nesithombe-skrini sokuthi isebenza. Uchofoza ngazo ngayinye, wamukele ezinhle bese uthumela ezisele emuva ukuze zilungiswe. Isibali samathokheni sikhombisa ukuthi konke kusebenzise malini, futhi imodi ethi No Token Mode ikhona ezinsukwini zokonga. Bese udla ibhulakufesi, okungakasizi ngakho ama-ejenti. Ngesonto elilandelayo ungenza okufanayo, uphinde ubone ukuthi kuthatha isikhathi esingakanani. Awudingi ukuhlala usuku lonke ubheke isikrini, futhi ibhodi lihlala lilungele wena.","Okokuqala, ukuthi i-AI-gile ayiyona yini. Akuyona inkampani entsha, akuthengiswa, futhi akekho oqoqa idatha yakho. Yibhodi lamahhala elisebenza ekhompyutheni yakho, ngaphandle kwama-akhawunti, ngaphandle kwama-tracker nangaphandle kwamakhukhi. Yini yona: indawo eyodwa ehlelekile yokubona wonke amaphrojekthi e-AI ngasikhathi sinye, neqembu lama-ejenti enza amakhadi nawe uthatha izinqumo. Ihlanganisa amakhadi ahlobene, ilungisa izihloko ezididayo, futhi ibheka ukuthi ikhodi ihlala incane kangakanani. Ikhuluma izilimi ezingaba ngu-120, kusukela esiDashi nesiFlemish kuya kumphangi wasolwandle nesiKlingon. Abangani bangathumelana imilayezo, ngasese futhi ibethelwe. Yakhiwe nguRich nenqwaba yama-ejenti anesineke, ikakhulukazi isebenzisa yona ngokwayo. Iku-pre-alpha evaliwe, ngakho inobukhali kwezinye izindawo. Uma kuzwakala kumnandi, cela kahle futhi ungangena kusenesikhathi. Kuyibhodi elincane elinenhliziyo, elenzelwe ukuba lisize abantu abangenaso isikhathi sokuhlola konke ngabo ngokwabo. Futhi kungumsebenzi oqhubekayo, kusakhula nsuku zonke."]}],"quips":{"1":"Igama elilodwa. Lilukhuni. Mhlawumbe lilukhuni kakhulu.","3":"Amagama amathathu. Seliqinisile kunamakhasi amaningi emikhiqizo.","8":"Amagama ayisishiyagalombili. Kusamfushane kuno-stand-up.","21":"Ubude bungamaphoyinti ezindaba, ngendlela. Yebo, kunjalo.","55":"Amagama angamashumi amahlanu nanhlanu. Amakhadi amabili aphelile ngenkathi ufunda lokho.","144":"Lena yinde. Alikho elingu-233. Ama-ejenti aye ukulala."}},"timeline":{"first-idea.name":"Umbono wokuqala","first-idea.line":"Ingxoxo yokuqala nya, ngaphambi kokuba kube khona ikhodi.","first-board.name":"Ibhodi lokuqala","first-board.line":"Ibhodi elilandelela ukwakhiwa kwalo: amakhadi, amakholomu, donsa uphonse, amaphrojekthi.","team-roles.name":"Iqembu nezindima","team-roles.line":"Amaphrofayela ama-ejenti, amathempulethi eqembu, izikhala nokuthi ngubani owenzani.","install.name":"Ukufaka nokukhishwa","install.line":"I-zip umngani angayifaka, ukuzibuyekeza, amashaneli nokubuyela emuva.","usage-saver.name":"Ukonga ukusetshenziswa","usage-saver.line":"Linganisa izindleko zokusebenza, gcina ikhodi incane, onge umkhawulo wakho.","friends.name":"Abangani nokwabelana","friends.line":"Imilayezo eyimfihlo, isidlulisi esixubekile, izimemo, izindima namaphrojekthi abelwanayo.","languages.name":"Izilimi","languages.line":"Yonke imibhalo yesikrini ifayelini lolimi, kuqala ngesiDashi nesiFlemish.","ai-tester.name":"Umhloli we-AI","ai-tester.line":"Umhloli uhlola ukudluliselwa ngakunye kuqala bese ekhombisa ayekubonile.","website.name":"Iwebhusayithi","website.line":"I-aigile.lol, i-teaser nalesi sikhathi.","streaming.name":"Ingxoxo nokusakaza","streaming.line":"I-Discord, i-Twitch, i-OBS, imodi yomsakazi, ama-GIF nama-emoji.","no-ai.name":"Uhlelo olungenayo i-AI","no-ai.line":"Ibhodi labantu abakhipha ikhodi ngaphandle kwe-AI, namabhodi omphakathi.","night-watch.name":"Ukuqapha ebusuku","night-watch.line":"Umqaphi ne-Scrum Master baqhubekisa amaqembu emsebenzini ngenkathi ulele.","p-more.name":"Konke okunye","p-more.line":"Imibono emincane ekhona isalindele ithuba layo.","p-android.name":"Ifoni ne-Android","p-android.line":"Finyelela ibhodi lakho ofonini, bese kuba uhlelo lwangempela lwe-Android.","p-release.name":"I-alpha nangale kwayo","p-release.line":"I-alpha evaliwe, isayithi eliphilayo, bese i-beta.","p-languages.name":"Izilimi eziningi","p-languages.line":"Izilimi ezingaphezu kwekhulu, nemodi yokucwiliswa yabafundi.","p-engines.name":"Izinjini ze-AI eziningi","p-engines.line":"Khetha i-Claude, i-Codex noma i-Gemini ku-ejenti ngayinye.","p-pro.name":"Umkhuba wochwepheshe","p-pro.line":"Amalebula obungozi, amasango okuhlanganisa, amakhadi ezehlakalo nezivikelo.","p-self.name":"Ukukunakekela","p-self.line":"Imodi yokukhathala, izikhumbuzi zokuzinakekela ne-4:20.","p-servers.name":"Amaseva nobukhulu","p-servers.line":"Izilungiselelo zamaseva jikelele, izindima nokuhlela ukukhula.","p-livestream.name":"Okungeziwe kokusakaza","p-livestream.line":"Ingxoxo ye-Twitch, ama-emoji ngokwezifiso nombono womphakathi ophilayo."},"words":{"button":"📖 Amagama ochwepheshe","h":"📖 Amagama achaziwe","intro":"Amagama ozohlangana nawo ku-AI-gile, ngolimi olulula: ukwakha, ukushintsha ngokuphepha, ukugcina kusebenza kubantu abakusebenzisayo, nokusebenza njengethimba ne-AI.","search":"Sesha igama…","none":"Alikho igama elifana nalelo.","close":"Vala","count":{"one":"igama elingu-{count}","other":"amagama angu-{count}"},"groups":[{"id":"build","name":"🛠️ Ukwakha"},{"id":"change","name":"🔀 Ukushintsha ngokuphepha"},{"id":"run","name":"🛎️ Ukuqhuba isevisi"},{"id":"team","name":"🤝 Ukusebenza njengethimba (nange-AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"I-folda yekhodi yephrojekthi nomlando wayo ophelele wama-commit, kaningi igcinwa ku-GitHub futhi.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Umugqa ohlukile womsebenzi ekhodini, ukuze izinguquko zenziwe ngaphandle kokuthinta inguqulo eyinhloko.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Isithombe esigciniwe sekhodi, esinenothi elifushane lokushintshile. Ungabuyela kunye noma nini.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Ukuthumela izithombe ezigciniwe (ama-commit) ukusuka kule khompyutha uye ku-GitHub, ukuze kugcinwe isipele futhi kwabelwane."},{"id":"merge","g":"build","word":"Merge","text":"Ukuhlanganisa izinguquko ze-branch emuva enguqulweni eyinhloko."},{"id":"pr","g":"build","word":"Pull request","text":"Ukucela ukuthi izinguquko ze-branch zihlolwe futhi zihlanganiswe enguqulweni eyinhloko.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ukuhlela ikhodi ngaphandle kokushintsha okwenzayo: amafayela amancane, amagama acacile, ukuphindaphinda okuncane."},{"id":"bug","g":"build","word":"Bug","text":"Into engasebenzi ngendlela okufanele isebenze ngayo.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Ukuzama ucezu lomsebenzi oqediwe ukubona ukuthi wenza okucelwe, ngaphambi kokuwamukela.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Isifinyezo se-quality assurance, okusho ukuqinisekisa ikhwalithi: ukuhlola okuzenzakalelayo okwenziwa ngaphambi kokuthi noma yini iphile. Uma i-QA ibomvu, kukhona okwehlulekile, futhi akukwazi ukuphila kuze kulungiswe lokho.","also":["ukuhlolwa kwekhwalithi","quality assurance","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Ukubeka inguqulo entsha ukuthi iphile, isibonelo kuseva lapho abantu bayisebenzisa khona."},{"id":"release","g":"change","word":"Ukukhishwa","text":"Iqoqo elinegama lomsebenzi oqediwe eliphila ndawonye, linamanothi amafushane ngokushintshile. 🚀 Ukukhishwa kubhala lawo manothi kusuka emakhadini aqediwe.","also":["i-release","release","releases"]},{"id":"rollback","g":"change","word":"Ukubuyela emuva","text":"Ukubuyela enguqulweni yokugcina eyayisebenza uma entsha idala inkinga. Ku-AI-gile kwenza uhlu lokuhlola lwezinyathelo zokuhlehlisa ezibhalwe kushintsho ngalunye.","also":["i-rollback","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Okuphilayo","text":"Inguqulo yangempela abantu abayisebenzisayo, hhayi ikhophi yokuzama izinto. Ukufaka okuthile lapho kubizwa ngokukuphilisa. Abathuthukisi bakubiza nangokuthi i-production.","also":["ukuphila","bukhoma","live","production"],"noTip":1},{"id":"change","g":"change","word":"Ushintsho","text":"Ushintsho oluhleliwe entweni abantu abathembele kuyo, olubhalwa kuqala: yini, kungani, ubungozi, nini, nokuthi lungahlehliswa kanjani. Qala ngokuthi 🔀 Phakamisa ushintsho.","also":["izinguquko","isicelo soshintsho","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Ubungozi","text":"Okuthile okungahamba kabi, okulinganiswa ngokuthi kungenzeka kangakanani nokuthi kungaba kubi kangakanani. ⚠️ Ubungozi kukugcina ohlwini olulodwa, amaphuzu aphezulu kuqala, ngakunye kunosuku lokuphinde ukubheke.","also":["izingozi","irejista yobungozi","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Iwindi loshintsho","text":"Izikhathi lapho izinguquko zingaphila khona, njengobusuku bangoLwesibili obuthule. Ngaphandle kwewindi ikhadi loshintsho alikwazi ukuqedwa, ngaphandle uma kuyisimo esiphuthumayo.","also":["amawindi ezinguquko","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Ukuvota okusheshayo ngaphambi nje kokuthi ushintsho luphile: wonke umuntu okufanele avume uthi Go noma No go. Kuqhubeka kuphela uma bevumelana.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Ukuvunywa","text":"Ukulinda u-yebo ngaphambi kokuthi umsebenzi uqale. Ikhadi eliphakanyiswe ngumngane, noma ushintsho, kulinda ku-✅ Ukuvunywa uze ukuvume noma ukwenqabe.","also":["ukuvuma","approval","approvals"]},{"id":"quiettime","g":"change","word":"Isikhathi sokuthula","text":"Isikhathi esithile, njenge-stream, idemo noma ubusuku, lapho kungekho okuphilayo. Amathimba aqhubeka nokusebenza nokuhlola, kodwa ukuphila kulinda kuze kuphele. Kwezinye izindawo kubizwa nge-change freeze.","also":["izikhathi zokuthula","quiet time","quiet times","change freeze"]},{"id":"service","g":"run","word":"Isevisi","text":"Okuthile okwakhile abantu abathembele kukho, njengewebhusayithi noma i-app, okunakekelwayo ukuze kuqhubeke kusebenza. Khetha ukuthi “Le phrojekthi iyisevisi” bese usho ukuthi inikezani, ubani oyisebenzisayo nokuthi ubani olindile.","also":["amasevisi","service","services"]},{"id":"uptime","g":"run","word":"Ukuhlola i-uptime","text":"Ukuhlola okuzenzakalelayo, njalo ngemizuzu embalwa, ukuthi isevisi yakho isaphendula yini. Uma kwehluleka izikhathi eziningana kulandelana, i-AI-gile ivula ikhadi lesigameko ngokwayo.","also":["i-uptime","uptime","uptime check","uptime checks"]},{"id":"statuspage","g":"run","word":"Ikhasi lesimo","text":"Ikhasi lomphakathi elikhombisa ukuthi isevisi iyasebenza yini (eluhlaza, ewolintshi noma ebomvu) kanye nesibuyekezo sakamuva, ukuze abantu abayisebenzisayo bazibonele esikhundleni sokubuza.","also":["amakhasi esimo","status page","status pages"]},{"id":"incident","g":"run","word":"Isigameko","text":"Okuthile okuphukile kubantu abakusebenzisayo khona manje, njengokuthi iwebhusayithi ayisebenzi. Ikhadi lesigameko 🔥 leqa ulayini: ukwenza kusebenze futhi kuza kuqala.","also":["izigameko","incident","incidents"]},{"id":"major","g":"run","word":"Isigameko esikhulu","text":"Isigameko esikhulu: abantu abaningi bathintekile, noma imali noma idatha isengozini. Inkinobho eyodwa ibeka wonke amathimba kuso (ukuhlangana), ivuse noma ubani olindile bese icela isibuyekezo sesimo njalo ngemizuzu engu-30.","also":["izigameko ezinkulu","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Ukulinda","text":"Ukuba ngulowo ophendulayo uma kukhona okuphukayo, ngisho nasebusuku. Isevisi ngayinye inelungu lethimba elilindile elivuswa kuqala ezigamekweni zayo.","also":["olindile","on call","on-call"]},{"id":"replyby","g":"run","word":"Isikhathi sokuphendula","text":"Ukuthi ikhadi lingalinda isikhathi esingakanani impendulo yokuqala, isibonelo ihora elilodwa esigamekweni. Ngemva kwalokho lithola iwashi elibomvu, ukuze kungabikho okukhohlwakala buthule. Kubizwa nangokuthi i-response target.","also":["reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Ukuhlaziywa kwesigameko","text":"Ukubheka emuva okufushane ngemva kwesigameko: kwenzekeni, yini esizile nokuthi yini okufanele ishintshwe, ngaphandle kokusola muntu. Isigameko asikwazi ukuvalwa ngaphandle kwakho. Kubizwa nangokuthi i-post-mortem.","also":["post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Inkinga","text":"Imbangela efihlekile ngemuva kwesigameko esisodwa noma ngaphezulu. Ikhadi lenkinga 🧩 liqoqa izigameko eziqhubeka zibuya, ukuze imbangela itholakale ilungiswe unomphela.","also":["izinkinga","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Imbangela eyinhloko","text":"Isizathu sangempela sokuthi kungani okuthile kuphukile, hhayi nje lokho okubone kungahambi kahle. Lungisa imbangela eyinhloko bese isigameko siyeka ukubuya.","also":["izimbangela eziyinhloko","root cause","root causes"]},{"id":"workaround","g":"run","word":"Indlela yesikhashana","text":"Indlela yokugcina izinto zisebenza kuze kube yilapho ukulungisa kwangempela sekulungile, njengokuqala kabusha okuthile uma kubambeka. Ibhalwa ekhadini lenkinga ukuze kungabikho okufanele akuthole futhi.","also":["izindlela zesikhashana","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Iphutha elaziwayo","text":"Inkinga imbangela yayo eseqondakala futhi enendlela yesikhashana, kodwa engakalungiswa. 🧩 Amaphutha aziwayo awabala ohlwini, ukuze wonke umuntu asebenzise indlela yesikhashana esikhundleni sokuphinda amba.","also":["amaphutha aziwayo","known error","known errors"]},{"id":"runbook","g":"run","word":"I-runbook","text":"Imiyalelo yesinyathelo ngesinyathelo yokulungisa uhlobo lwenkinga olwaziwayo, ukuze kwenziwe ngendlela efanayo, ngokushesha, njalo. Ngemva kwesigameko esikhulu ithimba lingaphakamisa i-runbook ukuze uyivume.","also":["runbook","runbooks","ama-runbook"]},{"id":"backup","g":"run","word":"Isipele","text":"Ikhophi elondoloziwe yedatha yakho yangaphambilini, ongabuyela kuyo uma okuthile kulahlekile noma konakele. I-AI-gile yenza isipele samabhodi akho nsuku zonke.","also":["izipele","i-backup","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Ukubuyisela","text":"Ukubuyisa idatha isuka esipeleni. Isipele sibaluleke ngempela kuphela uma wazi ukuthi singabuyiselwa, ngakho kufanele ukuzama ngezikhathi ezithile.","also":["buyisela","kubuyiselwe","restore","restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Imibono nomsebenzi ongakahlelwa. Akukho okusetshenzwa kukho kuze kuhambe kuya ku-Okufanele kwenziwe."},{"id":"sprint","g":"team","word":"Sprint","text":"Isikhathi esifushane somsebenzi (kaningi isonto noma amabili) onamakhadi avunyelwene okufanele aqedwe.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Ukubheka okusheshayo: ilungu ngalinye leqembu lenzeni, lenzani ngokulandelayo, nokuthi yini ebamisayo.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ibhodi elinezingqimba (Okufanele kwenziwe, Kuyaqhubeka, Kuphelile) lapho amakhadi ahamba esuka kwesobunxele aye kwesokudla njengoba umsebenzi wenzeka."},{"id":"wip","g":"team","word":"Umkhawulo we-WIP","text":"Umsebenzi oqhubekayo: amakhadi amaningi isingqimba okufanele sibambe, ukuze iqembu liqede izinto ngaphambi kokuqala ezengeziwe.","also":["WIP"]},{"id":"dod","g":"team","word":"Incazelo yokuqeda","text":"Uhlu olufushane lwethimba lokuthi “kuqediwe” kusho ukuthini, njengokuthi kuhloliwe futhi kuchaziwe, ngaphambi kokuthi ikhadi linikezwe wena. Iwele layo, Incazelo yokulungela, isho ukuthi ikhadi licace ngokwanele nini ukuze liqalwe.","also":["Definition of Done","Definition of Ready","Incazelo yokulungela","DoD","DoR"]},{"id":"testpile","g":"team","word":"Isitaki sokuhlola","text":"Amakhadi aqediwe alinde ukuthi uwazame, elinye emva kwelinye. Yamukela elilodwa noma ulibuyisele nenothi, bese kuvela elilandelayo.","also":["test pile","test piles"]},{"id":"retro","g":"team","word":"Ukubuyekeza","text":"Ukubheka emuva ukuthi ithimba lisebenza kanjani, ukuze nivumelane ngento eyodwa yokwenza kangcono. Ku-AI-gile ukubuyekeza kuphakamisa ushintsho ezindleleni zokusebenza zethimba, bese wena uthi Hamba noma Hhayi okwamanje.","also":["i-retro","retro","retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Ukubuyekezwa ngontanga","text":"Elinye iso: enye i-AI ihlola umsebenzi wekhadi ngalinye ngaphambi kokuthi lifike kuwe, ukuze amaphutha ambalwa adlule.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Ukuhlangana","text":"Wonke umuntu uyangena: wonke amathimba ashiya omunye umsebenzi ukuze asize iphrojekthi eyodwa ephuthumayo ize ixazululwe. Amanye amaphrojekthi alinda okwamanje.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Lowo ogcina umsebenzi uhamba: ubona amakhadi abambekile, ugqugquzela amathimba futhi akukhumbuze okulindile. Ku-AI-gile, i-Lead Scrum Master yenza lokhu kuyo yonke iphrojekthi.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"I-AI esebenza yodwa emsebenzini: ifunda ikhodi, yenze izinguquko, iqhube ukuhlola, ibike emuva.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Iyunithi lapho ukusetshenziswa kwe-AI kubalwa khona: cishe izinhlamvu ezimbalwa zombhalo ezifundwayo noma ezibhaliwe. Ama-token ambalwa, uhlelo olusele lukhulu.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Umyalo omncane osebenza wodwa ngesikhathi esimisiwe, isb. lapho iseshini ye-AI iqala, ukuze iqembu lizwe amakhomenti akho.","also":["hooks"]}]}};
